INSERT INTO content (id,kind,slug,title,category,status,published_at,updated_at,data) VALUES ('seed-why-domestic-manufacturing','articles','why-domestic-manufacturing','Why More Brands Are Bringing Production Back to the U.S.','Industry News','published','2026-09-12','2026-09-26T00:00:00.000Z','{"title":"Why More Brands Are Bringing Production Back to the U.S.","slug":"why-domestic-manufacturing","category":"Industry News","summary":"Shorter lead times, smaller minimums and full visibility on the line are changing how emerging labels plan their seasons.","body":"For years, the default playbook for a growing label was simple: design locally, produce overseas, wait. That math is changing. Freight volatility, higher minimums and the need to react mid-season have pushed more brands to look closer to home.\n\n## Speed is the new margin\n\nWhen your design team and the sewing line share a building, a fit comment becomes a revised sample the same week.\n\n- Sampling in 10 - 14 days\n- Bulk in 4 - 6 weeks\n- Reorders without re-quoting freight\n\n![Fabric being cut in the pattern room](/formyson/images/cutting.jpg)\n\n> \"We launched two drops in the time it used to take us to approve one sample.\"\n\n## What to ask a domestic partner\n\nAsk who owns the pattern, how QC is documented, and what happens when a trim is late. The answers tell you more than a price sheet. [Talk to our team](/formyson/contact/) about your next program.","author":"LOOMWORKS Editorial","publishedAt":"2026-09-12","status":"published","cover":{"url":"/formyson/images/why-domestic-manufacturing.jpg","alt":"Why More Brands Are Bringing Production Back to the U.S."},"gallery":[],"specs":[],"tags":["Industry News","Manufacturing","Made in USA"],"seoTitle":"","seoDescription":""}');
INSERT INTO content (id,kind,slug,title,category,status,published_at,updated_at,data) VALUES ('seed-reading-a-fabric-spec','articles','reading-a-fabric-spec','How to Read a Fabric Spec Sheet Like a Pattern Maker','Craftsmanship','published','2026-08-28','2026-09-26T00:00:00.000Z','{"title":"How to Read a Fabric Spec Sheet Like a Pattern Maker","slug":"reading-a-fabric-spec","category":"Craftsmanship","summary":"GSM, gauge, shrinkage and hand feel: a practical guide to the numbers that decide how a garment wears.","body":"For years, the default playbook for a growing label was simple: design locally, produce overseas, wait. That math is changing. Freight volatility, higher minimums and the need to react mid-season have pushed more brands to look closer to home.\n\n## Speed is the new margin\n\nWhen your design team and the sewing line share a building, a fit comment becomes a revised sample the same week.\n\n- Sampling in 10 - 14 days\n- Bulk in 4 - 6 weeks\n- Reorders without re-quoting freight\n\n![Fabric being cut in the pattern room](/formyson/images/cutting.jpg)\n\n> \"We launched two drops in the time it used to take us to approve one sample.\"\n\n## What to ask a domestic partner\n\nAsk who owns the pattern, how QC is documented, and what happens when a trim is late. The answers tell you more than a price sheet. [Talk to our team](/formyson/contact/) about your next program.","author":"Design Team","publishedAt":"2026-08-28","status":"published","cover":{"url":"/formyson/images/reading-a-fabric-spec.jpg","alt":"How to Read a Fabric Spec Sheet Like a Pattern Maker"},"gallery":[],"specs":[],"tags":["Craftsmanship","Manufacturing","Made in USA"],"seoTitle":"","seoDescription":""}');
INSERT INTO content (id,kind,slug,title,category,status,published_at,updated_at,data) VALUES ('seed-case-study-capsule-launch','articles','case-study-capsule-launch','From Sketch to Shelf in 9 Weeks: A Capsule Launch','Case Studies','published','2026-08-03','2026-09-26T00:00:00.000Z','{"title":"From Sketch to Shelf in 9 Weeks: A Capsule Launch","slug":"case-study-capsule-launch","category":"Case Studies","summary":"How a Los Angeles streetwear label took a 6-piece capsule from first sketch to retail with one partner.","body":"For years, the default playbook for a growing label was simple: design locally, produce overseas, wait. That math is changing. Freight volatility, higher minimums and the need to react mid-season have pushed more brands to look closer to home.\n\n## Speed is the new margin\n\nWhen your design team and the sewing line share a building, a fit comment becomes a revised sample the same week.\n\n- Sampling in 10 - 14 days\n- Bulk in 4 - 6 weeks\n- Reorders without re-quoting freight\n\n![Fabric being cut in the pattern room](/formyson/images/cutting.jpg)\n\n> \"We launched two drops in the time it used to take us to approve one sample.\"\n\n## What to ask a domestic partner\n\nAsk who owns the pattern, how QC is documented, and what happens when a trim is late. The answers tell you more than a price sheet. [Talk to our team](/formyson/contact/) about your next program.","author":"Production Team","publishedAt":"2026-08-03","status":"published","cover":{"url":"/formyson/images/case-study-capsule-launch.jpg","alt":"From Sketch to Shelf in 9 Weeks: A Capsule Launch"},"gallery":[],"specs":[],"tags":["Case Studies","Manufacturing","Made in USA"],"seoTitle":"","seoDescription":""}');
INSERT INTO content (id,kind,slug,title,category,status,published_at,updated_at,data) VALUES ('seed-garment-dye-explained','articles','garment-dye-explained','Garment Dye vs. Piece Dye: What Changes on the Rack','Craftsmanship','published','2026-07-16','2026-09-26T00:00:00.000Z','{"title":"Garment Dye vs. Piece Dye: What Changes on the Rack","slug":"garment-dye-explained","category":"Craftsmanship","summary":"The dye stage shapes color depth, shrinkage and cost. Here is how we decide for each program.","body":"For years, the default playbook for a growing label was simple: design locally, produce overseas, wait. That math is changing. Freight volatility, higher minimums and the need to react mid-season have pushed more brands to look closer to home.\n\n## Speed is the new margin\n\nWhen your design team and the sewing line share a building, a fit comment becomes a revised sample the same week.\n\n- Sampling in 10 - 14 days\n- Bulk in 4 - 6 weeks\n- Reorders without re-quoting freight\n\n![Fabric being cut in the pattern room](/formyson/images/cutting.jpg)\n\n> \"We launched two drops in the time it used to take us to approve one sample.\"\n\n## What to ask a domestic partner\n\nAsk who owns the pattern, how QC is documented, and what happens when a trim is late. The answers tell you more than a price sheet. [Talk to our team](/formyson/contact/) about your next program.","author":"Design Team","publishedAt":"2026-07-16","status":"published","cover":{"url":"/formyson/images/garment-dye-explained.jpg","alt":"Garment Dye vs. Piece Dye: What Changes on the Rack"},"gallery":[],"specs":[],"tags":["Craftsmanship","Manufacturing","Made in USA"],"seoTitle":"","seoDescription":""}');
